pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 wei, so address(this).balance == 1
        vm.deal(address(c), 1);
        // The depositor calls setL1BlockValues; pass _number = 0, others arbitrary
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(0, 1, 2, bytes32(uint256(3)), 4, bytes32(uint256(5)), 6, 7);
        // For the reference C, number == 0; for the bug, number == uint64(address(this).balance) == 1
        assertTrue(c.number() == 0);
    }
