pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use specific distinct values for _number and _timestamp
        uint64 _number = 1;
        uint64 _timestamp = 999;
        uint256 _basefee = 0;
        bytes32 _hash = bytes32(uint256(0));
        uint64 _sequenceNumber = 0;
        bytes32 _batcherHash = bytes32(uint256(0));
        uint256 _l1FeeOverhead = 0;
        uint256 _l1FeeScalar = 0;

        // Call as the depositor account
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        // The correct contract stores _number in number, the bug stores _timestamp
        // So after the call, c.number() should equal _number (1) in the correct version
        // and equal _timestamp (999) in the buggy version.
        // We assert that c.number() == 1, which holds for the reference and fails for the mutant.
        assertTrue(c.number() == 1);
    }
}

