pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use the depositor account
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        uint64 maxUint64 = type(uint64).max;

        vm.prank(depositor);
        c.setL1BlockValues(
            1,               // _number
            100,             // _timestamp
            1000,            // _basefee
            bytes32(uint256(1)), // _hash
            maxUint64,       // _sequenceNumber — max value, +1 causes overflow in buggy version
            bytes32(uint256(2)), // _batcherHash
            2000,            // _l1FeeOverhead
            3000             // _l1FeeScalar
        );

        uint64 storedSequence = c.sequenceNumber();
        // Reference: storedSequence == maxUint64; Bug: storedSequence == 0
        assertTrue(storedSequence == maxUint64, "Sequence number should equal the input maxUint64; buggy version wraps to 0");
    }
}

